+        let next = (0.4 * n.sqrt()).max(c + 0.15);
+        if next >= DEPTH {
+            want.push(DEPTH);
+            break;
+        }
+        want.push(next);
+        c = next;
+        n += 1.0;
+    }
+    assert_eq!(cum.len(), want.len(), "{cum:?} vs {want:?}");
+    for (a, b) in cum.iter().zip(&want) {
